import type { TabBarListProps } from "../tab-bar.types";

import React, { forwardRef, useRef, useMemo } from "react";
import * as RadixTabs from "@radix-ui/react-tabs";
import { clsx } from "clsx";

import { TabBarClasses } from "../tab-bar.styles";
import { useVisibleTabBar } from "../hooks/use-visible-tab-bar";

import { OverflowMenu } from "./tab-bar-overflow";

export const TabBarList = forwardRef<HTMLDivElement, TabBarListProps & RadixTabs.TabsListProps>(
  ({ className, children, overflowMenuTriggerLabel, ...props }, ref) => {
    const listRef = useRef<HTMLDivElement | null>(null);
    const moreButtonRef = useRef<HTMLDivElement>(null);

    const { addTab, tabs } = useMemo(() => {
      const addTab: React.ReactElement[] = [];
      const tabs: React.ReactElement[] = [];
      React.Children.toArray(children).forEach((child) => {
        if (React.isValidElement(child)) {
          if ((child.type as { displayName?: string }).displayName === "TabBar.AddTab") {
            addTab.push(child);
          } else if ((child.type as { displayName?: string }).displayName === "Tab") {
            tabs.push(child);
          }
        }
      });
      return { addTab, tabs };
    }, [children]);

    const allTriggers = tabs;
    const allValues = useMemo(() => allTriggers.map((tab) => tab.props.value), [allTriggers]);
    const { visibleValues, overflowValues } = useVisibleTabBar(listRef, allValues, moreButtonRef);

    return (
      <div className={clsx(TabBarClasses.listWrapper, className)}>
        <RadixTabs.List
          ref={(node) => {
            listRef.current = node;
            if (typeof ref === "function") ref(node);
            else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
          }}
          className={TabBarClasses.list}
          {...props}
        >
          {allTriggers.map((child) => {
            const value = child.props.value;
            const isVisible = visibleValues.includes(value);

            return React.cloneElement(child, {
              "data-value": value,
              style: !isVisible
                ? { visibility: "hidden", position: "absolute", zIndex: -1 }
                : child.props.style,
            });
          })}

          {overflowValues.length > 0 && (
            <OverflowMenu
              allTriggers={allTriggers}
              moreButtonRef={moreButtonRef}
              overflowMenuTriggerLabel={overflowMenuTriggerLabel}
              overflowValues={overflowValues}
            />
          )}
          {addTab}
        </RadixTabs.List>
      </div>
    );
  },
);

TabBarList.displayName = "TabBar.List";
